const MODEL = 'gpt-4o-mini'; // switch to 'gpt-4o' for deeper analysis
const b = $json.body || {};
if (!b.job || !b.profile || !b.profile.resume) {
  throw new Error('Request must include { job, profile } with profile.resume set.');
}
return { json: {
  job: b.job,
  profile: b.profile,
  model: MODEL,
  requestBody: {
    model: MODEL,
    temperature: 0.2,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: 'You are a recruiting analyst. Read the internship posting and identify what the hiring team is actually screening for. Respond ONLY with JSON: {"top_priorities": [5-8 strings, ranked], "keywords_for_ats": [strings taken from the posting], "tone": string, "what_impresses": one paragraph, "what_to_avoid": one paragraph}.' },
      { role: 'user', content: 'POSTING\nTitle: ' + b.job.title + '\nCompany: ' + b.job.company + '\nDescription:\n' + (b.job.description || '') }
    ]
  }
} };

const src = $('Build analysis request').item.json;
const raw = $json.choices?.[0]?.message?.content || '{}';
let analysis;
try { analysis = JSON.parse(raw.replace(/^```(json)?/m, '').replace(/```\s*$/m, '').trim()); }
catch (e) { analysis = { top_priorities: [], keywords_for_ats: [], what_impresses: '', what_to_avoid: '' }; }

const p = src.profile;
return { json: {
  job: src.job,
  analysis,
  requestBody: {
    model: src.model,
    temperature: 0.3,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: 'You are an expert resume writer with one hard rule: NEVER fabricate. You may only reorder, reword, quantify-where-stated, and emphasize experiences and skills that ALREADY EXIST in the candidate\'s base resume and profile. You may not add tools, jobs, degrees, dates, or achievements that are not there. Tailor the resume to the posting by leading with the most relevant real material, mirroring the posting\'s vocabulary where it truthfully applies, and trimming irrelevant content. Respond ONLY with JSON: {"tailored_resume": full plain-text resume, "cover_letter": 150-220 word cover letter in the candidate\'s voice grounded only in real experience, "changes_made": [strings explaining each change], "honesty_check": confirm in one sentence that nothing was invented}.' },
      { role: 'user', content: 'HIRING TEAM PRIORITIES (from analysis):\n' + JSON.stringify(analysis) + '\n\nPOSTING\nTitle: ' + src.job.title + '\nCompany: ' + src.job.company + '\nDescription:\n' + (src.job.description || '') + '\n\nCANDIDATE\nName: ' + (p.name || '') + '\nEmail: ' + (p.email || '') + '\nSkills: ' + (p.skills || '') + '\nInterests: ' + (p.interests || '') + '\nEducation: ' + (p.education || '') + '\nLinks: ' + (p.links || '') + '\n\nBASE RESUME:\n' + p.resume }
    ]
  }
} };

const src = $('Build tailoring request').item.json;
const raw = $json.choices?.[0]?.message?.content || '{}';
let out;
try { out = JSON.parse(raw.replace(/^```(json)?/m, '').replace(/```\s*$/m, '').trim()); }
catch (e) { out = { tailored_resume: raw, cover_letter: '', changes_made: ['Model returned non-JSON output; raw text placed in resume field.'], honesty_check: '' }; }
return { json: {
  ok: true,
  jobId: src.job.id,
  tailored_resume: out.tailored_resume || '',
  cover_letter: out.cover_letter || '',
  changes_made: out.changes_made || [],
  honesty_check: out.honesty_check || '',
  hiring_analysis: src.analysis,
  tailoredAt: new Date().toISOString()
} };
